using System;using System.Windows.Forms;namespace LlamaRental{    public partial class Form1 : Form    {        const double LLAMA_RENTAL_FEE = 74.50;        const double TAX_RATE = 0.0725;        public Form1()        {            InitializeComponent();        }        private void btnCalculate_Click(object sender, EventArgs e)        {            int llamaCount = (int)numLlamas.Value;            string size = "";            if (radSmall.Checked) size = "Small";            else if (radMedium.Checked) size = "Medium";            else if (radJumbo.Checked) size = "Jumbo";            string disposition = cboDisposition.SelectedItem?.ToString() ?? "Unknown";            double subtotal = llamaCount * LLAMA_RENTAL_FEE;            double tax = subtotal * TAX_RATE;            double total = subtotal + tax;            lblResult.Text = $"Renting {llamaCount} {size} llama(s) who are {disposition.ToLower()}.Total: ${total:F2}";        }    }}
